<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {AgentClient,type AgentProfile,type ProviderSelection,type ProviderOption,type MemoryDocument} from './client';
 import BotPermissions from './BotPermissions.svelte';
 import {updateBotPurpose,updateBotAvatar,avatarSelection} from './bot-purpose';
 import AvatarBuilder from '../avatar-studio/AvatarBuilder.svelte';
 import {getAvatar,encodeAvatar,isAllowedAvatarKey} from '../avatar-studio/avatar-model';
 import Orb from '../Orb.svelte';
 import CompanyAccountConnection from '../company/CompanyAccountConnection.svelte';
 export let accessSignal:AbortSignal;
 export let companyId:string;
 export let botId:string;
 export let botName:string='' ;
 export let membershipRevision:number=0;
 const dispatch=createEventDispatcher();
 let boundSignal:AbortSignal|undefined;let client:AgentClient|null=null,ready=false,loaded='',loading=true,saving='',tab='Profile',error='',notice='';
 let profile:AgentProfile|null=null,selection:ProviderSelection|null=null,options:ProviderOption[]=[],memory:MemoryDocument|null=null,caps:string[]=[];
 let avatarKey='';
 let name='',purpose='',instructions='',modelChoice='',memoryContent='',profileError='',providerError='',memoryError='',memoryWriteId='',memoryFingerprint='';
 const modelKey=(id:string|null,model:string|null)=>JSON.stringify([id,model]);
 $: scope=JSON.stringify([companyId,botId,membershipRevision]);
 $: if(ready&&scope!==loaded){loaded=scope;void load();}
 $: profileDirty=!!profile&&(name!==profile.name||purpose!==profile.purpose||instructions!==profile.instructions);
 $: avatarDirty=!!profile&&avatarKey!==(avatarSelection(profile.avatarKey)||avatarSelection(profile.avatar));
 $: modelDirty=!!selection&&modelChoice!==modelKey(selection.connectionId,selection.model);
 $: memoryDirty=!!memory&&memoryContent!==memory.content;
 $: validModel=options.some(o=>o.models.some(m=>modelKey(o.connectionId,m)===modelChoice));
 $: dirty=profileDirty||avatarDirty||modelDirty||memoryDirty;
 function parentRevoked(){deny({status:403});}
 $: if(ready&&boundSignal!==accessSignal){boundSignal?.removeEventListener('abort',parentRevoked);boundSignal=accessSignal;boundSignal?.addEventListener('abort',parentRevoked,{once:true});if(boundSignal?.aborted)parentRevoked();}
 async function load(){if(accessSignal?.aborted){parentRevoked();return;}client?.close();const current=client=new AgentClient(companyId,botId,()=>localStorage.token||'');loading=true;saving='';profile=null;avatarKey='';selection=null;memory=null;options=[];caps=[];name='';purpose='';instructions='';modelChoice='';memoryContent='';error='';notice='';profileError='';providerError='';memoryError='';memoryWriteId='';memoryFingerprint='';
  await Promise.allSettled([
   current.profile().then(v=>{if(client===current){profile=v;name=v.name;purpose=v.purpose;instructions=v.instructions;avatarKey=avatarSelection(v.avatarKey)||avatarSelection(v.avatar);}}).catch(e=>{if(client===current)profileError=e.message;}),
   current.providers().then(v=>{if(client===current){selection=v.selection;options=v.options;providerError=v.optionsError||'';modelChoice=modelKey(selection.connectionId,selection.model);}}).catch(e=>{if(client===current)providerError=e.message;}),
   current.memory().then(v=>{if(client===current){memory=v;memoryContent=v.content;}}).catch(e=>{if(client===current)memoryError=e.message;}),
   current.authority().then(v=>{if(client===current)caps=v;}).catch(e=>{if(client===current)deny(e);})
  ]);if(client===current)loading=false;
 }
 function deny(e:any){if([401,403,404].includes(e?.status)){saving='';loading=false;memoryWriteId='';memoryFingerprint='';notice='';client?.close();client=null;profile=null;avatarKey='';selection=null;memory=null;options=[];caps=[];name='';purpose='';instructions='';memoryContent='';modelChoice='';error='Access changed. Close this editor and reopen your company workspace.';dispatch('accesschanged',{status:e.status});return true;}return false;}
 async function save(section:string){if(!client||saving)return;const current=client;saving=section;error='';notice='';try{
  if(section==='Profile'&&profile){const result=await current.saveProfile(profile,{name,purpose,instructions});if(client!==current)return;profile=result;name=result.name;purpose=result.purpose;instructions=result.instructions;updateBotPurpose(companyId,botId,result.purpose);dispatch('saved',{companyId,botId,name:result.name,revision:result.revision});}
  else if(section==='Avatar'&&profile&&isAllowedAvatarKey(avatarKey)){const result=await current.saveAvatar(profile,avatarKey);if(client!==current)return;profile=result;avatarKey=avatarSelection(result.avatarKey)||avatarSelection(result.avatar);updateBotPurpose(companyId,botId,result.purpose);updateBotAvatar(companyId,botId,avatarKey);dispatch('saved',{companyId,botId,name:result.name,revision:result.revision});}
  else if(section==='Intelligence'&&selection&&validModel){const [connectionId,model]=JSON.parse(modelChoice);const result=await current.saveProvider(selection,connectionId,model);if(client!==current)return;selection=result.selection;options=result.options;providerError=result.optionsError||'';modelChoice=modelKey(selection.connectionId,selection.model);}
  else if(section==='Memory'&&memory){const fingerprint=JSON.stringify([memory.revision,memoryContent]);if(memoryFingerprint!==fingerprint){memoryFingerprint=fingerprint;memoryWriteId=crypto.randomUUID();}const result=await current.saveMemory(memory,memoryContent,memoryWriteId);if(client!==current)return;memory=result;memoryContent=result.content;memoryWriteId='';memoryFingerprint='';}
  if(client===current)notice=section+' saved.';
 }catch(e){if(client===current&&!deny(e))error=(e as Error).message+' Your unsaved changes are kept. Reload the latest settings before trying again.';}finally{if(client===current)saving='';}}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null)deny({status:401});}
 onMount(()=>{ready=true;window.addEventListener('storage',session);return()=>window.removeEventListener('storage',session);});onDestroy(()=>{client?.close();boundSignal?.removeEventListener('abort',parentRevoked);});
</script>

<section class="agent-settings" aria-label="Agent settings" aria-busy={loading}>
 <header><button class="back" on:click={()=>dispatch('close',{dirty})} aria-label="Back to your AI team">← <span>Your AI team</span></button><div class="heading"><div class="avatar"><Orb size={64} name={profile?.name||botName} {avatarKey}/></div><div><p class="eyebrow">AGENT SETTINGS</p><h1>{profile?.name||botName||'Configure your agent'}</h1><p class="subtitle">Give your teammate a clear role and the right context.</p></div><span class="scope-label">Company agent</span></div></header>
 <nav aria-label="Agent settings sections">{#each ['Profile','Intelligence','Memory','Permissions'] as item}<button class:active={tab===item} on:click={()=>tab=item}>{item}{#if (item==='Profile'&&(profileDirty||avatarDirty))||(item==='Intelligence'&&modelDirty)||(item==='Memory'&&memoryDirty)}<span class="dot" aria-label="Unsaved changes"></span>{/if}</button>{/each}</nav>
 <div class="content">
 {#if error}<div class="alert" role="alert">{error}</div>{/if}{#if notice}<div class="notice" role="status">✓ {notice}</div>{/if}
 {#if loading}<div class="empty" role="status">Loading your agent’s settings…</div>
 {:else if tab==='Profile'}
  {#if profile}<section class="avatar-picker" aria-label="Bot avatar"><h2>Design your avatar</h2><p class="hint">Mix original SVG faces, parts, colors and gradients. Appearance is company-wide when saved.</p><div class="studio">
  <AvatarBuilder config={getAvatar(avatarKey,profile.name||botName)} disabled={!profile.canManage||!!saving} on:change={(event)=>avatarKey=encodeAvatar(event.detail.config)} on:preset={(event)=>avatarKey=event.detail.key}/>
 </div>{#if profile.canManage}<button type="button" class="primary" disabled={!avatarDirty||!isAllowedAvatarKey(avatarKey)||!!saving} on:click={()=>save('Avatar')}>{saving==='Avatar'?'Saving…':'Save avatar for this bot'}</button>{/if}
 </section><form on:submit|preventDefault={()=>save('Profile')}><div class="section-title"><h2>A role with a purpose</h2><p>These instructions guide this agent in company conversations.</p></div>
   <label for="agent-name">Agent name</label><input id="agent-name" bind:value={name} maxlength="100" required disabled={!profile.canManage||!!saving} placeholder="e.g. Agata"/>
   {#if profile.source!=='directory'}<label for="agent-purpose">Purpose <span>A short introduction for your team</span></label><textarea id="agent-purpose" bind:value={purpose} maxlength="2000" rows="3" disabled={!profile.canManage||!!saving} placeholder="What does this agent help your team accomplish?"/>{/if}
   <label for="agent-instructions">System instructions</label><p class="hint">Describe responsibilities, tone, and how this agent should approach its work.</p><textarea id="agent-instructions" class="instructions" bind:value={instructions} maxlength="16000" rows="10" disabled={!profile.canManage||!!saving} placeholder="You help the team…"/><div class="field-meta"><span>Applied to new agent runs</span><span>{instructions.length.toLocaleString()} / 16,000</span></div>
   <footer><p>{profile.canManage?'Changes are shared with your company.':profile.source==='directory'?'Existing directory profile · Editing requires the company profile service.':'Only company owners and admins can edit this profile.'}</p>{#if profile.canManage}<button class="primary" disabled={!profileDirty||!name.trim()||!!saving}>{saving==='Profile'?'Saving…':'Save profile'}</button>{/if}</footer>
  </form>{:else}<div class="empty">{profileError||'Agent profile is unavailable.'}</div>{/if}
 {:else if tab==='Intelligence'}
  <div class="section-title"><h2>The right model for the job</h2><p>Choose from your company’s existing provider connections.</p></div>{#if caps.includes('connections.manage')}<CompanyAccountConnection {companyId} {accessSignal} on:connected={load}/>{/if}
  {#if selection}<form on:submit|preventDefault={()=>save('Intelligence')}><div class="selection-status"><span class="status-dot" class:blocked={selection.status!=='ready'}></span>{selection.status==='ready'?'Company model connected':selection.status==='unconfigured'?'No model selected':selection.status.replaceAll('_',' ')}</div>{#if selection.model}<p class="saved-model">{selection.provider} · {selection.model}</p>{/if}{#if providerError}<div class="alert" role="alert">{providerError}</div>{/if}{#if selection.mode==='account_default'}<div class="account-default"><strong>Account default</strong><p class="hint">This agent follows the current default provider and model of the connected account. Choose a company connection below to give this agent its own model without changing the account default.</p></div>{/if}{#if options.length}<label for="agent-model">Provider and model</label><select id="agent-model" bind:value={modelChoice} disabled={!caps.includes('shared_bot.choose_provider')||!!saving}><option value="">Choose a model</option>{#each options as option}{#each option.models as model}<option value={modelKey(option.connectionId,model)}>{option.mode==='account_default'?'Owner account default':option.provider==='hosted'?'StarliDigital hosted':option.provider} · {model}</option>{/each}{/each}</select>{/if}<p class="hint">Credentials stay in company connection settings. This editor does not access provider secrets.</p><footer><p>Selection revision {selection.configurationRevision}</p>{#if caps.includes('shared_bot.choose_provider')&&options.length}<button class="primary" disabled={!modelDirty||!validModel||!!saving}>{saving==='Intelligence'?'Saving…':'Save model'}</button>{/if}</footer></form>{:else}<div class="empty">{providerError||'Model settings are unavailable.'}</div>{/if}
 {:else if tab==='Memory'}
  <div class="section-title"><h2>Context that stays with your agent</h2><p>Company memory is shared with permitted company members. Private conversation memories stay separate.</p></div>
  {#if memory}<form on:submit|preventDefault={()=>save('Memory')}><label for="agent-memory">Company memory</label><textarea id="agent-memory" bind:value={memoryContent} rows="14" disabled={!caps.includes('write')||!!saving} placeholder="Useful facts, preferences, and context for your team…"/><footer><p>Revision {memory.revision} · Company audience</p>{#if caps.includes('write')}<button class="primary" disabled={!memoryDirty||!!saving}>{saving==='Memory'?'Saving…':'Save memory'}</button>{/if}</footer></form>{:else}<div class="empty">{memoryError||'Company memory is unavailable for this agent.'}</div>{/if}
 {:else}<BotPermissions {companyId} {botId} botName={profile?.name||botName||'this agent'} {accessSignal} {membershipRevision} effectiveCapabilities={profile?.toolCapabilities||[]} on:accesschanged={(e)=>dispatch('accesschanged',e.detail)} on:changed={(e)=>{if(profile&&e.detail.effectiveCapabilities)profile={...profile,toolCapabilities:e.detail.effectiveCapabilities};dispatch('permissionschanged',e.detail);}}/>{/if}
 {#if !loading&&client}<button class="reload" disabled={!!saving} on:click={load}>{dirty?'Discard unsaved changes and reload':'Reload latest settings'}</button>{/if}
 </div>
</section>

<style>
 .agent-settings{flex:1;min-height:0;overflow-y:auto;box-sizing:border-box;width:100%;max-width:1060px;margin:0 auto;padding:38px 46px 48px;color:#17243F;font-family:inherit}.back{display:flex;gap:10px;align-items:center;color:#71809A;background:none;border:0;padding:0;font-size:14px;cursor:pointer}.back:hover{color:#3466F6}.heading{display:flex;align-items:center;gap:20px;margin:32px 0}.avatar{width:74px;height:74px;flex-shrink:0;border:1px solid #DCE6FF;border-radius:23px;background:linear-gradient(140deg,#EEF3FF,#EAF0FF);display:grid;place-items:center;color:#3466F6;font-size:31px;font-weight:500}.eyebrow{color:#3466F6;font-size:10px;letter-spacing:2px;margin:0 0 7px;font-weight:650}h1{font-size:27px;font-weight:550;letter-spacing:-.7px;line-height:1.2;margin:0}.subtitle{color:#71809A;font-size:13px;margin:8px 0 0}.scope-label{margin-left:auto;border:1px solid #E6EBF4;border-radius:20px;color:#71809A;font-size:11px;padding:7px 12px;white-space:nowrap}nav{display:flex;border-bottom:1px solid #E6EBF4;gap:26px}nav button{display:flex;align-items:center;gap:7px;background:none;border:0;border-bottom:2px solid transparent;padding:15px 0;color:#71809A;font-size:13px;cursor:pointer}nav button.active{color:#3466F6;border-color:#3466F6}.dot{width:5px;height:5px;background:#3466F6;border-radius:50%}.content{max-width:760px;padding-top:29px}.section-title{margin-bottom:29px}h2{font-size:19px;font-weight:500;letter-spacing:-.3px;margin:0 0 9px}.section-title p,.hint{font-size:12px;line-height:1.7;color:#71809A;margin:0}.hint{margin:-1px 0 12px}label{display:block;font-size:12px;color:#17243F;margin:22px 0 10px;font-weight:500}label span{color:#71809A;font-weight:400;margin-left:8px;font-size:11px}input,textarea,select{width:100%;border:1px solid #E6EBF4;background:#FFFFFF;border-radius:9px;padding:12px 14px;font:inherit;font-size:13px;color:#17243F;outline:none;box-sizing:border-box;transition:border-color .15s}textarea{resize:vertical;line-height:1.75}input:focus,textarea:focus,select:focus{border-color:#3466F6;box-shadow:0 0 0 2px #3466F610}input:disabled,textarea:disabled,select:disabled{opacity:.6}.instructions{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px}.field-meta{display:flex;justify-content:space-between;font-size:10px;color:#71809A;margin-top:9px}footer{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:28px;padding-top:23px;border-top:1px solid #E6EBF4}footer p{color:#71809A;font-size:11px;line-height:1.6;margin:0}.primary{background:#3466F6;color:#FFFFFF;border:0;border-radius:8px;padding:10px 19px;font-size:12px;font-weight:650;cursor:pointer;white-space:nowrap}.primary:hover{background:#2855D8}.primary:disabled{opacity:.4;cursor:default}.reload{background:none;border:0;color:#71809A;font-size:11px;padding:0;margin-top:26px;text-decoration:underline;text-underline-offset:3px;cursor:pointer}.alert,.notice{padding:12px 15px;border-radius:8px;font-size:12px;line-height:1.6;margin-bottom:20px}.alert{color:#A62D35;background:#FFF4F4;border:1px solid #F3D2D5}.notice{color:#286A46;background:#EFF8F2;border:1px solid #D8EDDF}.empty{padding:40px 0;color:#71809A;font-size:13px}.selection-status{font-size:12px;color:#71809A;display:flex;align-items:center;gap:8px;margin-bottom:26px}.status-dot{height:6px;width:6px;border-radius:50%;background:#86b49a}.status-dot.blocked{background:#d6a66b}button:focus-visible{outline:2px solid #3466F6;outline-offset:4px}@media(max-width:720px){.agent-settings{padding:24px 20px}.heading{gap:14px}.avatar{width:57px;height:57px;border-radius:18px;font-size:25px}h1{font-size:22px}.scope-label{display:none}nav{gap:20px;overflow:auto}footer{align-items:flex-start;gap:16px}.subtitle{font-size:12px}}
.avatar-picker{margin-bottom:30px;padding-bottom:24px;border-bottom:1px solid #e2e8f0}.studio{margin:18px 0}.avatar-picker>.primary{margin-top:16px}
</style>




